-- نجم أبو الفضل — الهايجين = اللبس بس: التيشرت إجباري على الكل، والإيبرون والكاسكيت والأفرهيد والجلافز حسب القسم
-- البنود المطلوبة لكل قسم في الإعدادات (hyItems). أي قسم مش موجود ← التيشرت بس. (مدير التشغيل بيعدّلها من الإعدادات)
update public.najm_settings set data = jsonb_set(coalesce(data, '{}'::jsonb), '{hyItems}', '{"قسم البقاله": [0, 1, 2, 3, 4], "قسم التصنيع": [0, 1, 2, 3, 4], "قسم المعمل": [0, 1, 2, 3, 4], "قسم الايس كريم": [0, 1, 2, 3, 4], "قسم التركي": [0, 1, 2, 3, 4], "bakery": [0, 1, 2, 3, 4], "قسم البيض": [0, 1, 2, 3, 4], "قسم الفاكهه": [0, 1, 2, 3, 4], "قسم الرنجه": [0, 1, 2, 3, 4], "انتاج معلبات": [0, 1, 2, 3, 4], "قسم الجوده": [0, 1, 2, 3, 4], "خدمه العملاء": [0, 2], "قسم الكاشير": [0, 2], "vip": [0, 2]}'::jsonb)
  where id = 1 and not (coalesce(data, '{}'::jsonb) ? 'hyItems');
